 static final UUID A=UUID.fromString("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"),B=UUID.fromString("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"),ALPHA=UUID.fromString("11111111-1111-1111-1111-111111111111"),BETA=UUID.fromString("22222222-2222-2222-2222-222222222222");
 @Autowired MockMvc mvc;@Autowired EmployeeRepository employees;@Autowired EmployeeLifecycleEventRepository events;@Autowired OrganizationChangeEventRepository organizationEvents;@Autowired DepartmentRepository departments;@Autowired DesignationRepository designations;@Autowired WorkforceWorkspaceRepository workspaces;@MockitoBean TenantAuthorityClient authority;
 @BeforeEach void setup(){events.deleteAll();organizationEvents.deleteAll();employees.deleteAll();departments.deleteAll();designations.deleteAll();workspaces.deleteAll();when(authority.validate(anyString(),anyString(),any(),nullable(String.class))).thenAnswer(i->context(i.getArgument(0),i.getArgument(1),i.getArgument(3)));when(authority.requireEmployeeLimit(anyString(),anyInt(),anyString(),any(),nullable(String.class))).thenAnswer(i->{int n=i.getArgument(1);if(n>2)throw new IllegalStateException("limit");return context(i.getArgument(0),i.getArgument(2),i.getArgument(4));});}
 @Test void missingInventedAndManagerContextsFailClosed()throws Exception{mvc.perform(get("/api/workforce/employees")).andExpect(status().isUnauthorized());request(get("/api/workforce/employees"),"unknown","alpha","owner").andExpect(status().isForbidden());request(get("/api/workforce/employees"),"a","beta","owner").andExpect(status().isForbidden());request(get("/api/workforce/employees"),"a","alpha","manager").andExpect(status().isForbidden());}
