 @Test void rejectsCrossWorkspaceReferencesAndAllUuidInjection()throws Exception{request(post("/api/workforce/departments").contentType(MediaType.APPLICATION_JSON).content("{\"key\":\"sales\",\"name\":\"Sales\"}"),"b","beta","owner").andExpect(status().isCreated());create("a","alpha","owner","EMP-001","sales",null).andExpect(status().isBadRequest());String id=A.toString();request(post("/api/workforce/employees").contentType(MediaType.APPLICATION_JSON).content(employee("EMP-002",null,null).replace("}",",\"organizationId\":\""+id+"\",\"workspaceId\":\""+id+"\",\"productId\":\""+id+"\",\"planId\":\""+id+"\",\"entitlementId\":\""+id+"\"}")),"a","alpha","owner").andExpect(status().isBadRequest());}
