 @Test void malformedInputAndDuplicateWorkspaceKeysAreRejected()throws Exception{create("a","alpha","owner","bad code",null,null).andExpect(status().isBadRequest());create("a","alpha","owner","EMP-001",null,null).andExpect(status().isCreated());create("a","alpha","owner","EMP-001",null,null).andExpect(status().isConflict());}
 @Test void concurrentCreationCannotBypassEmployeeLimit()throws Exception{request(post("/api/workforce/departments").contentType(MediaType.APPLICATION_JSON).content("{\"key\":\"seed\",\"name\":\"Seed\"}"),"a","alpha","owner").andExpect(status().isCreated());when(authority.requireEmployeeLimit(eq("a"),anyInt(),anyString(),any(),eq("alpha"))).thenAnswer(i->{if((int)i.getArgument(1)>1)throw new IllegalStateException("limit");return new TrustedWorkforceContext(A,"a","alpha",WorkforceRole.OWNER,user("a","owner"),ALPHA);});CompletableFuture<Integer> one=CompletableFuture.supplyAsync(()->requestStatus("EMP-101"));CompletableFuture<Integer> two=CompletableFuture.supplyAsync(()->requestStatus("EMP-102"));assertThat(List.of(one.join(),two.join())).containsExactlyInAnyOrder(201,403);assertThat(employees.countByWorkspaceIdAndStatus(A,com.lexorion.workforce.domain.EmploymentStatus.ACTIVE)).isEqualTo(1);}
 @Test void lifecycleGraphAndAppendOnlyHistoryAreEnforced()throws Exception{create("a","alpha","owner","EMP-001",null,null).andExpect(status().isCreated());request(post("/api/workforce/employees/EMP-001/leave"),"a","alpha","admin").andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ON_LEAVE"));request(post("/api/workforce/employees/EMP-001/suspend"),"a","alpha","owner").andExpect(status().isConflict());request(get("/api/workforce/employees/EMP-001/history"),"a","alpha","owner").andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(2)).andExpect(jsonPath("$[0].action").value("CREATED")).andExpect(jsonPath("$[1].action").value("PLACED_ON_LEAVE")).andExpect(jsonPath("$[0].id").doesNotExist());request(post("/api/workforce/employees/EMP-001/terminate"),"a","alpha","owner").andExpect(status().isOk());request(post("/api/workforce/employees/EMP-001/activate"),"a","alpha","owner").andExpect(status().isConflict());assertThat(events.count()).isEqualTo(3);}
 @Test void profilePatchCannotChangeStatusAndNormalizesEmail()throws Exception{create("a","alpha","owner","emp-001",null,null).andExpect(status().isCreated()).andExpect(jsonPath("$.employeeCode").value("EMP-001"));request(patch("/api/workforce/employees/EMP-001").contentType(MediaType.APPLICATION_JSON).content("{\"workEmail\":\"  NEW@Example.COM  \"}"),"a","alpha","admin").andExpect(status().isOk()).andExpect(jsonPath("$.workEmail").value("new@example.com"));request(patch("/api/workforce/employees/EMP-001").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"TERMINATED\"}"),"a","alpha","owner").andExpect(status().isBadRequest());}
