 @Test void filtersInactiveReferencesHistoryTenancyAndMemberDenial()throws Exception{request(post("/api/workforce/departments").contentType(MediaType.APPLICATION_JSON).content("{\"key\":\"engineering\",\"name\":\"Engineering\"}"),"a","alpha","owner").andExpect(status().isCreated());create("a","alpha","owner","EMP-001","engineering",null).andExpect(status().isCreated());request(patch("/api/workforce/departments/engineering").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"INACTIVE\"}"),"a","alpha","owner").andExpect(status().isOk());request(get("/api/workforce/employees?status=ACTIVE&departmentKey=engineering&search=ada"),"a","alpha","admin").andExpect(status().isOk()).andExpect(jsonPath("$.content.length()").value(1));create("a","alpha","owner","EMP-002","engineering",null).andExpect(status().isBadRequest());request(get("/api/workforce/employees/EMP-001/history"),"b","beta","owner").andExpect(status().isNotFound());request(get("/api/workforce/employees"),"a","alpha","member").andExpect(status().isForbidden());}
 @Test void concurrentActivationsCannotBypassLimit()throws Exception{createWithStatus("EMP-101","ON_LEAVE").andExpect(status().isCreated());createWithStatus("EMP-102","SUSPENDED").andExpect(status().isCreated());when(authority.requireEmployeeLimit(eq("a"),anyInt(),anyString(),any(),eq("alpha"))).thenAnswer(i->{if((int)i.getArgument(1)>1)throw new IllegalStateException("limit");return new TrustedWorkforceContext(A,"a","alpha",WorkforceRole.OWNER,user("a","owner"),ALPHA);});CompletableFuture<Integer> one=CompletableFuture.supplyAsync(()->lifecycleStatus("EMP-101","activate"));CompletableFuture<Integer> two=CompletableFuture.supplyAsync(()->lifecycleStatus("EMP-102","activate"));assertThat(List.of(one.join(),two.join())).containsExactlyInAnyOrder(200,403);assertThat(employees.countByWorkspaceIdAndStatus(A,com.lexorion.workforce.domain.EmploymentStatus.ACTIVE)).isEqualTo(1);}
 @Test void concurrentCreateActivateAndDeactivateRemainWithinLimit()throws Exception{create("a","alpha","owner","EMP-ACTIVE",null,null).andExpect(status().isCreated());createWithStatus("EMP-LEAVE","ON_LEAVE").andExpect(status().isCreated());when(authority.requireEmployeeLimit(eq("a"),anyInt(),anyString(),any(),eq("alpha"))).thenAnswer(i->{if((int)i.getArgument(1)>1)throw new IllegalStateException("limit");return new TrustedWorkforceContext(A,"a","alpha",WorkforceRole.OWNER,user("a","owner"),ALPHA);});CompletableFuture<Integer> create=CompletableFuture.supplyAsync(()->requestStatus("EMP-NEW"));CompletableFuture<Integer> activate=CompletableFuture.supplyAsync(()->lifecycleStatus("EMP-LEAVE","activate"));CompletableFuture<Integer> deactivate=CompletableFuture.supplyAsync(()->lifecycleStatus("EMP-ACTIVE","resign"));CompletableFuture.allOf(create,activate,deactivate).join();assertThat(deactivate.join()).isEqualTo(200);assertThat(employees.countByWorkspaceIdAndStatus(A,com.lexorion.workforce.domain.EmploymentStatus.ACTIVE)).isLessThanOrEqualTo(1);}
